    cols = len(grid[0])

    # Find separator value (value that appears in complete rows or columns)
    sep_rows = [i for i in range(rows) if all(grid[i][j] == grid[i][0] for j in range(cols))]
    sep_cols = [j for j in range(cols) if all(grid[i][j] == grid[0][j] for i in range(rows))]

    if sep_rows:
        sep_val = grid[sep_rows[0]][0]
    elif sep_cols:
        sep_val = grid[0][sep_cols[0]]
    else:
        sep_val = 9

    # Create output grid
    output = [[9] * cols for _ in range(rows)]

    # Get sets for faster lookup
    sep_rows_set = set(sep_rows)
    sep_cols_set = set(sep_cols)

    # Fill separator rows
    for r in sep_rows:
        for c in range(cols):
            output[r][c] = sep_val

    # Fill separator columns
    for c in sep_cols:
        for r in range(rows):
            output[r][c] = sep_val

    # Process each region
    for r_start in range(rows):
        if r_start not in sep_rows_set:
            # Find end of row region
            r_end = rows
            for r2 in sep_rows:
                if r2 > r_start:
                    r_end = r2
                    break

            # Find regions within this row strip
            c_start = 0
            while c_start < cols:
                if c_start not in sep_cols_set:
